(function(root){
'use strict';
const SIZE=6,ORTH=[[0,-1],[-1,0],[1,0],[0,1]],DIAG=[[-1,-1],[1,-1],[-1,1],[1,1]],DIRS=[...ORTH,...DIAG];
const copy=s=>({...s,pieces:s.pieces.map(p=>({...p}))});
const xy=p=>[p%SIZE,Math.floor(p/SIZE)],distance=(a,b)=>Math.abs(a%SIZE-b%SIZE)+Math.abs(Math.floor(a/SIZE)-Math.floor(b/SIZE));
function board(s){const b=Array(36).fill(null);for(const p of s.pieces)b[p.pos]=p;return b;}
function actions(s,side){const b=board(s),out=[];for(const p of s.pieces){if(p.side!==side||p.type==='king')continue;const [x,y]=xy(p.pos),dirs=p.type==='guard'?DIRS:ORTH;for(const [dx,dy]of dirs){const n=p.type==='jumper'?2:1,nx=x+dx*n,ny=y+dy*n,to=ny*6+nx;if(nx<0||nx>=6||ny<0||ny>=6||s.walls.includes(to))continue;const q=b[to];if(p.type==='pusher'&&q){let bx=nx+dx,by=ny+dy,push=by*6+bx;if(bx<0||bx>=6||by<0||by>=6||s.walls.includes(push)||b[push])continue;out.push({id:p.id,to,push});}else if(!q||q.side!==side){out.push({id:p.id,to});}}}return out;}
function apply(s,m){const n=copy(s),p=n.pieces.find(p=>p.id===m.id),q=n.pieces.find(q=>q.pos===m.to);if(q){if(m.push!==undefined)q.pos=m.push;else n.pieces=n.pieces.filter(p=>p.id!==q.id);}p.pos=m.to;return n;}
function evaluate(s){const king=s.pieces.find(p=>p.type==='king');if(!king)return 100000;const white=s.pieces.filter(p=>p.side==='w');if(!white.some(p=>p.type!=='pusher'))return -100000;let value=0;const weights={knight:110,jumper:150,pusher:85,hunter:95,guard:145,king:0};for(const p of s.pieces)value+=(p.side==='w'?1:-1)*weights[p.type];const a=actions(s,'w'),b=actions(s,'b');let nearest=20;for(const p of white){if(p.type!=='pusher')nearest=Math.min(nearest,distance(p.pos,king.pos)/(p.type==='jumper'?2:1));}value-=nearest*20;value+=a.length*2-b.length;let danger=0;for(const m of b){const q=s.pieces.find(p=>p.pos===m.to&&p.side==='w');if(q)danger=Math.max(danger,weights[q.type]*0.6);}value-=danger;const threats=a.filter(m=>m.to===king.pos&&m.push===undefined).length;value+=threats*850;const defenders=s.pieces.filter(p=>p.side==='b'&&p.type!=='king');value-=defenders.filter(p=>distance(p.pos,king.pos)<=2).length*12;return value;}
const aiCache=new Map();
function stateKey(s){return s.pieces.map(p=>p.id+':'+p.type+':'+p.side+':'+p.pos).join('|')+'/'+s.walls.join(',');}
// Black minimizes the best white reply: two-ply minimax, recalculated from the live position.
function chooseAI(s){const k=stateKey(s);if(aiCache.has(k))return aiCache.get(k);const options=actions(s,'b');let best=null,bestScore=Infinity;for(const move of options){const after=apply(s,move),reply=actions(after,'w');let worst=reply.length?-Infinity:-100000;for(const answer of reply){const score=evaluate(apply(after,answer));if(score>worst)worst=score;if(worst>bestScore)break;}const tie=evaluate(after)*0.001;const score=worst+tie;if(score<bestScore){bestScore=score;best=move;}}if(aiCache.size>100000)aiCache.clear();aiCache.set(k,best);return best;}
function transition(s,m){let n=apply(s,m);n.turn=s.turn+1;n.lastAI=null;if(!n.pieces.some(p=>p.type==='king')){n.status='win';return n;}const ai=chooseAI(n);if(ai){n=apply(n,ai);n.lastAI=ai;}if(!n.pieces.some(p=>p.side==='w'&&p.type!=='pusher')||!actions(n,'w').length)n.status='lose';return n;}
function step(s,m){if(s.status!=='play')return null;const legal=actions(s,'w').find(a=>a.id===m.id&&a.to===m.to);if(!legal)return null;const n=transition(s,legal);if(n.status!=='win'&&n.turn>=n.limit){n.status='lose';n.reason='limit';}else if(n.status==='lose')n.reason='pieces';return n;}
function initial(level){return {pieces:level.pieces.map(p=>({...p})),walls:[...level.walls],turn:0,limit:level.limit,status:'play',lastAI:null};}
root.Game={SIZE,copy,actions,apply,evaluate,chooseAI,stateKey,transition,step,initial,distance};
})(typeof module!=='undefined'?module.exports:window);
